// Planka row n8n-wip-pull posts {event, data:{item, included}, prevData, user} with ?event=&board_id=&list=&card_id=.
// Act on cardMoved, or on a card_type value written to a card in TODO (a card born in TODO). Everything else stops here.
const q = $json.query || {};
const b = $json.body || {};
const d = b.data || {};
const inc = d.included || {};
const event = String(q.event || b.event || '');
const list = String(q.list || ((inc.lists || [])[0] || {}).name || '').trim().toUpperCase();
const cf = (inc.customFields || [])[0] || {};
const board_id = String(q.board_id || (d.item || {}).boardId || ((inc.boards || [])[0] || {}).id || '');
const act = board_id !== '' && (event === 'cardMoved' || (event === 'customFieldValueUpdate' && cf.name === 'card_type' && list === 'TODO'));
// The tenant rides on the CARD (keycloak_tenant_id): definition id -> name, then this card's value for that id.
// Measured 2026-11-06: real wip-pull payloads DO carry it. ABSENT STAYS ABSENT: '' means no override (the credential's tenant).
const item = d.item || {};
const nameOf = {};
(inc.customFields || []).forEach(f => { nameOf[String(f.id)] = String(f.name); });
let tenant_id = (q.tenant_id !== undefined && q.tenant_id !== null) ? String(q.tenant_id).trim() : '';
if (!tenant_id) {
  (inc.customFieldValues || []).forEach(v => {
    if (item.id !== undefined && String(v.cardId) === String(item.id) && nameOf[String(v.customFieldId)] === 'keycloak_tenant_id') {
      const t = String(v.content || '').trim();
      if (t) tenant_id = t;
    }
  });
}
return [{ json: { act: act, event: event, list: list, board_id: board_id, card_id: String(q.card_id || ''), tenant_id: tenant_id } }];

// R346 WIP pull (George 2026-11-03; WIP N = at most N cards in READY+DOING, George 10-31). One run = one board.
// Emits one item per TODO card to move to READY; zero items = nothing to pull (the chain stops).
const STRUCTURAL = ['project_start_request_analysis', 'project_setup', 'project_phase_start'];
const CLOSURE = ['project_phase_closure', 'project_closure'];
const p = $('Resolve project').first().json || {};
// A kata board is RM-linked but its kata runs its own n8n: never pull on it.
if (String(p.project_type || '').trim().toLowerCase() === 'kata') return [];
const inc = ($('Get board').first().json || {}).included || {};
if (!Array.isArray(inc.cards)) throw new Error('Get board returned no included.cards for board ' + p.planka_board_id);
const ids = p.planka_list_ids || {};
if (!ids.READY) throw new Error('the board link of project ' + p.project_id + ' has no READY list id');
const listOf = {};
Object.keys(ids).forEach(k => { listOf[String(ids[k])] = k; });
(inc.lists || []).forEach(l => { if (!listOf[String(l.id)] && l.name) listOf[String(l.id)] = String(l.name).trim().toUpperCase(); });
// Several field groups may carry the same field name: map every field id to its name.
const fieldName = {};
(inc.customFields || []).forEach(f => { fieldName[String(f.id)] = f.name; });
const fields = {};
(inc.customFieldValues || []).forEach(v => {
  const n = fieldName[String(v.customFieldId)];
  if (n) (fields[String(v.cardId)] = fields[String(v.cardId)] || {})[n] = v.content;
});
const parseRequires = (raw) => {
  const s = (raw === undefined || raw === null) ? '' : String(raw).trim();
  if (s === '') return { ok: true, ids: [] };
  try { const a = JSON.parse(s); return Array.isArray(a) ? { ok: true, ids: a.map(String) } : { ok: false, ids: [] }; }
  catch (e) { return { ok: false, ids: [] }; }
};
const cards = inc.cards.map(c => {
  const f = fields[String(c.id)] || {};
  const r = parseRequires(f.requires);
  return { id: String(c.id), list: listOf[String(c.listId)] || null, position: Number(c.position) || 0,
    card_type: String(f.card_type || '').trim(), phase: String(f.phase || '').trim(), requires: r.ids, requires_ok: r.ok };
});
const inList = (l) => cards.filter(c => c.list === l);
const done = new Set(inList('DONE').map(c => c.id));
const live = cards.filter(c => c.list !== 'DROPPED'); // a DROPPED card is abandoned: it holds nothing open
const busy = inList('READY').length + inList('DOING').length;
const lim = p.effective_wip_limit;
// RM effective_wip_limit null = no limit.
const wip = (lim === null || lim === undefined) ? Infinity : ((typeof lim === 'number' && Number.isFinite(lim)) ? lim : 1);
let slots = Math.max(0, wip - busy);
const closureReady = live.every(c => CLOSURE.indexOf(c.card_type) >= 0 || c.list === 'DONE');
const candidates = inList('TODO')
  .filter(c => c.card_type !== '' && c.requires_ok && c.requires.every(id => done.has(id)))
  .sort((a, b) => a.position - b.position);
const out = [];
for (const c of candidates) {
  let rule = null;
  if (STRUCTURAL.indexOf(c.card_type) >= 0) rule = 'structural';
  else if (CLOSURE.indexOf(c.card_type) >= 0) { if (closureReady) rule = 'closure'; }
  else if (slots > 0) { rule = 'work'; slots -= 1; }
  if (rule) out.push({ json: { card_id: c.id, card_type: c.card_type, rule: rule, ready_list_id: String(ids.READY),
    project_id: p.project_id, board_id: String(p.planka_board_id || ''), wip_limit: Number.isFinite(wip) ? wip : null, busy: busy } });
}
return out;

// Resolve project runs with continueRegularOutput: a failed lookup arrives here as {error, statusCode}.
// 404 = this board is not linked to an RM project (not a conveyor board): stop quietly.
// Any other failure (RM 5xx, auth, transport) is NOT "not a conveyor board": throw, so the pull is not silently lost.
const r = $input.first().json || {};
if (!r.error) return [{ json: r }];
const status = Number(r.statusCode) || null;
if (status === 404 || String(r.errorCode || '') === 'planka_board_not_linked') return [];
throw new Error('wip.pull: RM getProjectByPlankaBoard failed for board ' + $('Event filter').first().json.board_id + ' (status ' + (status || 'none') + '): ' + String(r.error).slice(0, 500));

// Re-entrancy guard. BOTH webhooks (n8n-per-flow and n8n-wip-pull) are subscribed to this
// board, so two runs can select the same TODO card; without a re-read the second run moves
// it again, and every move re-fires cardMoved and starts another {card_type}.READY chain
// (measured 2026-11-08: project_setup.READY ran twice concurrently — 1218318 + 1218320).
// `Card now` is a planka card:get, so the card sits under `item`.
const ids = $('Resolve project').first().json.planka_list_ids || {};
if (!ids.TODO) throw new Error('wip.pull: the project link has no TODO list id');
if (!ids.READY) throw new Error('wip.pull: the project link has no READY list id');
const out = [];
for (const item of $input.all()) {
  const body = item.json || {};
  const card = body.item || body;
  if (!card || !card.id || !card.listId) {
    throw new Error('wip.pull: card:get returned no id/listId: ' + JSON.stringify(body).slice(0, 300));
  }
  // A concurrent run already moved it: this item stops here, so no second move and no
  // second chain. (The first run's move is what the card is already sitting on.)
  if (String(card.listId) !== String(ids.TODO)) continue;
  // Emit the ORIGINAL pull decision: `Move to READY` keeps reading $json.card_id and
  // $json.ready_list_id and is not touched by this guard.
  out.push({ json: { card_id: String(card.id), ready_list_id: String(ids.READY) } });
}
return out;
